    let mut score = post_residual as f64;

    // 1. Dead Space Penalty: Heavily penalize gaps that are too small to fit typical future items (e.g., < 15).
    // If post_residual is in the "danger zone" (1..15), increase score to discourage this placement.
    if post_residual > 0 && post_residual < 15 {
        score += (15.0 - post_residual as f64) * 8.5;
    }

    // 2. Lookahead Synergy: If the next item fits in the resulting post_residual, reward this bin placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 1.2;
    }

    // 3. Open Bin Pressure: If this is an existing bin (not a new empty one), penalize based on current bin count.
    // This pushes the algorithm to consolidate items into fewer bins early on.
    if bin_residual < bin_capacity {
        score += (open_bins_count as f64) * 0.5;
    } else {
        // Penalty for opening a new bin: Only open if forced or if current open bins are heavily fragmented.
        score += 20.0 + (mean_residual * 0.2);
    }

    // 4. Scarcity Logic: If this is the only bin that fits the item, make it highly desirable (low score).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // 5. Final refinement: Favor bins with lower residuals (Best-Fit principle) to keep gaps uniform.
    score += (bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Harmonic Penalty: Heavily penalize residuals that are small but non-zero (the "fragmentation trap").
    // We favor perfect fits (post_residual == 0) and larger residuals that can accommodate future items.
    if post_residual > 0 {
        score += (bin_capacity as f64) / (post_residual as f64 + 1.0);
    }

    // 2. Lookahead Logic: If the next item fits into the current post_residual, prioritize this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (bin_capacity - post_residual) as f64 * 1.5;
    }

    // 3. New Bin Threshold: If this is an empty bin, only pick it if the current fitting bins 
    // result in a very poor post_residual (high fragmentation).
    if bin_residual == bin_capacity {
        // Only open a new bin if the mean residual of existing bins is already tight (less than 20),
        // suggesting that fitting the current item would leave a useless fragment.
        if mean_residual > 20.0 {
            score += 50.0; // Penalize new bin creation if existing bins have space.
        } else {
            score -= 10.0; // Reward new bin if existing bins are already too fragmented.
        }
    } else {
        // 4. Harmonic Alignment: Reward placements where the residual is a multiple of the item_size 
        // or fits into a "harmonic class" (e.g., 100/2, 100/3, 100/4).
        let harmonic_fit = (bin_capacity % (post_residual + 1)) as f64;
        score += harmonic_fit * 0.5;
    }

    // 5. Progression Scaling: As the stream nears completion, become more aggressive about filling
    // remaining bins rather than opening new ones.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        if bin_residual == bin_capacity {
            score += 100.0; // Extreme penalty for opening new bins at the end.
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Heuristic #56: Harmonic-Residual Balancing
    // We prioritize bins that result in post_residuals that are multiples of common item sizes
    // or leave "perfect" remaining space (near 0 or near capacity).

    let mut score = post_residual as f64;

    // Penalty for opening a new bin prematurely
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 150.0;
        } else {
            score -= 50.0;
        }
    }

    // Harmonic Class Logic: 
    // If the post_residual is a multiple of 10, it's statistically more likely to fit future items.
    if post_residual % 10 == 0 {
        score -= 15.0;
    }

    // Lookahead Coupling:
    // If next_item_size fits in the post_residual, reward this bin heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
        // Further reward if it leaves very little space after the next item
        if (post_residual - next_item_size) < 10 {
            score -= 20.0;
        }
    }

    // Penalize fragmented bins:
    // If this bin has a very small residual, it's likely "dead space".
    if post_residual < 10 && post_residual > 0 {
        score += 30.0;
    }

    // Capacity Fraction: 
    // Bias towards bins that maintain a mean residual closer to the global average.
    let residual_delta = (bin_residual as f64 - mean_residual).abs();
    score += residual_delta * 0.2;

    // Progression scaling: 
    // As the stream nears completion, become more aggressive about filling bins (less choosy).
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 10.0;

    score
}

