    if bin_residual == bin_capacity {
        // Base cost of opening a new bin is high; only take it if mean_residual is already very small
        // or if no other bins are available.
        score = 65.0 + (mean_residual * 0.5);
        if fitting_bins_count == 0 {
            score -= 50.0;
