    } else {
        // 4. Global pressure: As we near the end of the stream, prioritize consolidating
        let progress = step_index as f64 / total_items as f64;
        score += progress * (open_bins_count as f64 * 2.0);
    }

    // 5. Fitting count logic: If this is the last bin that can fit the item, prioritize it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    score
}

