pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base heuristic: Best Fit (minimize post_residual)
    let mut score = post_res;

    // Penalty for creating "dead space": residuals below 10 are often unfillable
    // given the item size range (10-80). We penalize values in the (0, 10) range 
    // quadratically to favor tighter fits or larger remaining spaces.
    if post_res > 0.0 && post_res < 10.0 {
        score += (10.0 - post_res).powi(2) * 5.0;
    }

    // Lookahead logic: if next_item_size is large, prefer bins with high post_residual
    // to accommodate the future item.
    if next_item_size > 0 {
        let lookahead_penalty = (next_item_size as f64 - post_res).max(0.0).powf(1.5);
        score += lookahead_penalty * 0.5;
    }

    // Dynamic pressure: As the stream progresses, discourage opening new bins 
    // unless the fit is extremely tight (Best Fit Decreasing dynamic).
    if bin_residual == bin_capacity {
        // High penalty for opening a new bin early in the stream, 
        // which scales down as we approach the end.
        score += 25.0 * (1.0 - progress * 0.5);
    }

    // Coupling with global state: Penalize bins that deviate significantly from 
    // the mean residual to maintain bin uniformity (load balancing).
