pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: prioritize bins that leave the smallest residual.
    // However, heavily penalize "sliver" residuals that are too small to fit typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 2. Harmonic Lookahead: If the next item is large, prioritize bins that can accommodate it.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 40.0;
    }

    // 3. New Bin Thresholding: If we are forced to open a new bin (bin_residual == bin_capacity),
    // compare the cost of doing so vs keeping an existing bin.
    if bin_residual == bin_capacity {
        // Only open a new bin if the current open bins are "cluttered" (mean_residual is low)
        // or if we have very few open bins relative to the stream progression.
        let progress = step_index as f64 / total_items as f64;
        score = 25.0 + (mean_residual * 0.5) - (progress * 10.0);
    } else {
        // 4. Harmonic Alignment: Reward placing items such that the post_residual
        // is a multiple of common item sizes, reducing "fragmentation".
        let alignment = (post_residual % 20) as f64;
        score += alignment;

        // 5. If this is the last chance to fit an item in an existing bin, prioritize it.
        if fitting_bins_count == 1 {
            score -= 30.0;
        }
    }

    // 6. Density balancing: Penalize opening too many bins early in the stream.
    score += (open_bins_count as f64) * 2.0 * (1.0 - (step_index as f64 / total_items as f64));

    score
