pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Best-Fit Penalty: Penalize large remaining space to prioritize filling bins (Best-Fit principle)
    // We favor smaller post_residual.

    // 2. Lookahead Synergy: If the next item fits into the current post_residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 1.5;
    }

    // 3. Fragmentation Avoidance: If post_residual is small but > 0, it creates "dead space".
    // Penalize residuals that are too small to fit common items (e.g., < 10).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 - progress);
    }

    // 4. Dynamic Thresholding for New Bins:
    // If this is a new bin (bin_residual == bin_capacity), only pick it if the current 
    // open bins are highly fragmented or if we are nearing the end of the stream.
    if bin_residual == bin_capacity {
        if open_bins_count == 0 {
            score = 0.0;
        } else {
            // Only open a new bin if the average residual is poor (high) or we have few fitting options.
            score = mean_residual * 0.8 + (1.0 - progress) * 20.0;
            if fitting_bins_count > 0 {
                score += 40.0; // Heavy penalty for opening new bin if existing ones work
            }
        }
    } else {
        // 5. Global State Balancing:
        // If we are late in the stream, prioritize closing bins (lower score) over keeping them open.
        score += (open_bins_count as f64) * progress * 0.5;
    }

    score
}
